class Solution:
    def mergeCloseCharacters(self, s: str, k: int) -> str:
        s = list(s)
        while True:
            hit = -1
            for i in range(len(s)):
                for j in range(i + 1, min(len(s), i + k + 1)):
                    if s[j] == s[i]:
                        hit = j
                        break
                if hit != -1:
                    break
            if hit == -1:
                return ''.join(s)
            del s[hit]

c.cpp:
class Solution {
public:
    string mergeCloseCharacters(string s, int k) {
        while (true) {
            int hit = -1;
            for (int i = 0; i < (int)s.size() && hit == -1; i++)
                for (int j = i + 1; j < (int)s.size() && j <= i + k; j++)
                    if (s[j] == s[i]) { hit = j; break; }
            if (hit == -1) return s;
            s.erase(s.begin() + hit);
        }
    }
};

