class Solution {
    public String mergeCloseCharacters(String s, int k) {
        StringBuilder sb = new StringBuilder(s);
        while (true) {
            int hit = -1;
            outer:
            for (int i = 0; i < sb.length(); i++)
                for (int j = i + 1; j < sb.length() && j <= i + k; j++)
                    if (sb.charAt(j) == sb.charAt(i)) { hit = j; break outer; }
            if (hit == -1) return sb.toString();
            sb.deleteCharAt(hit);
        }
    }
}

