var mergeCloseCharacters = function(s, k) {
    const a = s.split('');
    while (true) {
        let hit = -1;
        outer:
        for (let i = 0; i < a.length; i++)
            for (let j = i + 1; j < a.length && j <= i + k; j++)
                if (a[j] === a[i]) { hit = j; break outer; }
        if (hit === -1) return a.join('');
        a.splice(hit, 1);
    }
};
